using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Fermionic;
internal sealed class BcGhostQuartetCountDocument : IScribeDocumentDefinition
{
    private static DocumentBlock Node(string name, string prose, DescribeRole role = DescribeRole.Theorem) => Describe.Lean(
        DescribeId.Create("bc-ghost-quartet-count-" + name.Replace("_", "-").ToLowerInvariant()),
        DeclarationHandle.Create("D5/S3/Quantum/Fermionic/BcGhostQuartetCount." + name),
        H(name.Replace("_", " ")), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The actual original bc mode sum has a natural occupation count, a spectral inverse, a two-dimensional full ground and a one-dimensional literal relative ground.",
        H("Actual ghost quartet count on the original Fock carrier"), Blocks(
                Paragraph(Text("The carrier is CountableOccupationFock.Fock: complex finitely supported functions on finite subsets of the natural sites. Ket S is the original Finsupp.single S 1; vacuum is ket of the empty set. Creators and annihilators use the original Jordan-Wigner sign, minus one to the number of occupied sites strictly below the operated site. The b and c modes are exactly BcGhostFock.b and BcGhostFock.c, with annihilation cuts b at m at least minus one and c at n at least two. No tensor decomposition, dimension bound, spectral identity, positivity premise or additional state-finiteness premise is introduced. All operator products compose right to left; natural count scalars are cast into Complex.")),
                Node("U", "For positive k this is c at minus k composed with b at k plus b at minus k composed with c at k. The artificial natural-index zero term is zero. Products act from right to left. Original Lean signature: def U (k : \u2115) : Module.End \u2102 Fock", DescribeRole.Definition),
                Node("U_zero", "The zero branch in U_ket uses this simp identity to discard the artificial index zero. Original Lean signature: @[simp] theorem U_zero : U 0 = 0"),
                Node("U_pos", "U_ket uses this expansion for every strictly positive index before evaluating the two paired modes. Original Lean signature: theorem U_pos (k : \u2115) (hk : 0 < k) : U k = c (-(k : \u2124)) * b (k : \u2124) + b (-(k : \u2124)) * c (k : \u2124)"),
                Node("phase_insert_self", "annihilate_create_ket uses this simp identity to cancel the two original signs after insertion. Original Lean signature: @[simp] theorem phase_insert_self (j : \u2115) (S : Finset \u2115) : phase j (insert j S) = phase j S"),
                Node("phase_erase_self", "create_annihilate_ket uses this simp identity to cancel the two original signs after erasure. Original Lean signature: @[simp] theorem phase_erase_self (j : \u2115) (S : Finset \u2115) : phase j (S.erase j) = phase j S"),
                Node("phase_square", "Both same-site ket product proofs use this simp identity to cancel their two phase factors. Original Lean signature: @[simp] theorem phase_square (j : \u2115) (S : Finset \u2115) : phase j S * phase j S = 1"),
                Node("create_annihilate_ket", "The occupied odd and even branches in c_negative_b_positive_ket and b_negative_c_positive_ket use this original ket calculation; b0_eq_zero_iff_coefficients also uses it. Original Lean signature: theorem create_annihilate_ket (j : \u2115) (S : Finset \u2115) : (create j * annihilate j) (ket S) = if j \u2208 S then ket S else 0"),
                Node("annihilate_create_ket", "The exceptional k=1 branch of b_negative_c_positive_ket uses this hole calculation at site 1. Original Lean signature: theorem annihilate_create_ket (j : \u2115) (S : Finset \u2115) : (annihilate j * create j) (ket S) = if j \u2208 S then 0 else ket S"),
                Node("b_positive", "c_negative_b_positive_ket and M_b_positive use this original-mode correspondence at odd sites. Original Lean signature: theorem b_positive (k : \u2115) : b (k : \u2124) = annihilate (2 * k + 3)"),
                Node("c_negative", "c_negative_b_positive_ket and M_c_negative use this original-mode correspondence at odd sites. Original Lean signature: theorem c_negative (k : \u2115) : c (-(k : \u2124)) = create (2 * k + 3)"),
                Node("b_negative_one", "The k=1 ket and negative-b commutator branches use this simp correspondence with annihilation at site 1. Original Lean signature: @[simp] theorem b_negative_one : b (-1) = annihilate 1"),
                Node("c_positive_one", "The k=1 ket and positive-c commutator branches use this simp correspondence with creation at site 1. Original Lean signature: @[simp] theorem c_positive_one : c 1 = create 1"),
                Node("b_zero", "b0_down and b0_eq_zero_iff_coefficients use this correspondence with annihilation at the uncounted site 3. Original Lean signature: @[simp] theorem b_zero : b 0 = annihilate 3"),
                Node("b_negative_ge_two", "The even-site ket branch and M_b_negative use this correspondence for indices at least two. Original Lean signature: theorem b_negative_ge_two (k : \u2115) (hk : 2 \u2264 k) : b (-(k : \u2124)) = create (2 * (k - 2))"),
                Node("c_positive_ge_two", "The even-site ket branch and M_c_positive use this correspondence for indices at least two. Original Lean signature: theorem c_positive_ge_two (k : \u2115) (hk : 2 \u2264 k) : c (k : \u2124) = annihilate (2 * (k - 2))"),
                Node("c_negative_b_positive_ket", "U_ket uses this occupied odd-site branch of the actual paired mode. Original Lean signature: theorem c_negative_b_positive_ket (k : \u2115) (S : Finset \u2115) : (c (-(k : \u2124)) * b (k : \u2124)) (ket S) = if 2 * k + 3 \u2208 S then ket S else 0"),
                Node("b_negative_c_positive_ket", "U_ket uses this branch, including its separate site-1 hole case at k=1. Original Lean signature: theorem b_negative_c_positive_ket (k : \u2115) (hk : 0 < k) (S : Finset \u2115) : (b (-(k : \u2124)) * c (k : \u2124)) (ket S) = if k = 1 then (if 1 \u2208 S then 0 else ket S) else (if 2 * (k - 2) \u2208 S then ket S else 0)"),
                Node("localCount", "The odd occupied site is 2k+3 for positive k. At k=1 the second branch counts the hole at site 1. For k at least 2 it counts the occupied even site 2(k-2). Original Lean signature: def localCount (k : \u2115) (S : Finset \u2115) : \u2115", DescribeRole.Definition),
                Node("U_ket", "The capture proof and M_ket use this actual-mode local diagonal action. Original Lean signature: theorem U_ket (k : \u2115) (S : Finset \u2115) : U k (ket S) = (localCount k S : \u2102) \u2022 ket S"),
                Node("count", "The count is the cardinality of S with sites 1 and 3 erased, plus one precisely when site 1 is absent. Site 3 is uncounted; occupying site 1 removes a hole. Original Lean signature: def count (S : Finset \u2115) : \u2115", DescribeRole.Definition),
                Node("count_insert_regular", "count_erase_regular, count_surjective_relative and M_create_regular use the increase under insertion of a regular site. Original Lean signature: theorem count_insert_regular (j : \u2115) (S : Finset \u2115) (hj1 : j \u2260 1) (hj3 : j \u2260 3) (hj : j \u2209 S) : count (insert j S) = count S + 1"),
                Node("count_erase_regular", "M_annihilate_regular uses this exact count change on occupied regular sites. Original Lean signature: theorem count_erase_regular (j : \u2115) (S : Finset \u2115) (hj1 : j \u2260 1) (hj3 : j \u2260 3) (hj : j \u2208 S) : count S = count (S.erase j) + 1"),
                Node("count_insert_one", "count_erase_one and M_create_one use the reversed count change when the site-1 hole is filled. Original Lean signature: theorem count_insert_one (S : Finset \u2115) (h1 : 1 \u2209 S) : count (insert 1 S) + 1 = count S"),
                Node("count_erase_one", "M_annihilate_one uses this increase when deleting site 1 creates a hole. Original Lean signature: theorem count_erase_one (S : Finset \u2115) (h1 : 1 \u2208 S) : count (S.erase 1) = count S + 1"),
                Node("sum_localCount", "M_ket uses the parity bijections and exceptional hole term to identify the actual finite mode sum with count S. Explicit bijections enumerate the odd sites other than 1 and 3 and the even sites in S. Their parity partition and the exceptional hole give the count for every finite capture satisfying the displayed bounds. Original Lean signature: theorem sum_localCount (S : Finset \u2115) (N : \u2115) (hN : 3 \u2264 N) (hS : \u2200 j \u2208 S, j + 3 \u2264 N) : (\u2211 k \u2208 Finset.range N, localCount k S) = count S"),
                Node("localCount_zero_of_capture", "U_zero_above_capture uses this vanishing for every occupied basis state in the support of an actual Fock vector. Original Lean signature: theorem localCount_zero_of_capture (S : Finset \u2115) (k : \u2115) (hk : 3 \u2264 k) (hS : \u2200 j \u2208 S, j + 3 \u2264 k) : localCount k S = 0"),
                Node("occupied", "Take the finite union of the actual occupied site sets in the finitely supported input. Original Lean signature: def occupied (v : Fock) : Finset \u2115", DescribeRole.Definition),
                Node("capture", "The maximum occupied site plus three bounds every potentially nonzero positive summand for this actual input. Original Lean signature: def capture (v : Fock) : \u2115", DescribeRole.Definition),
                Node("site_capture", "U_zero_above_capture uses this bound for each site of each supported basis state. Original Lean signature: theorem site_capture (v : Fock) (S : Finset \u2115) (hS : S \u2208 v.support) (j : \u2115) (hj : j \u2208 S) : j + 3 \u2264 capture v"),
                Node("ket_expansion", "U_zero_above_capture and b0_eq_zero_iff_coefficients use this finite expansion of the original Fock vector. Original Lean signature: theorem ket_expansion (v : Fock) : (\u2211 S \u2208 v.support, v S \u2022 ket S) = v"),
                Node("U_zero_above_capture", "mode_support_subset uses the vanishing beyond the state-dependent capture. Original Lean signature: theorem U_zero_above_capture (v : Fock) (k : \u2115) (hk : capture v \u2264 k) : U k v = 0"),
                Node("mode_support_subset", "mode_support_finite and modeSum_eq_sum use this explicit finite support bound. Original Lean signature: theorem mode_support_subset (v : Fock) : Function.support (fun k => U k v) \u2286 (Finset.range (capture v) : Set \u2115)"),
                Node("mode_support_finite", "This is the all-state local-finiteness endpoint for the original positive paired modes. Every original finite-excitation state has a finite evaluated mode support. No finite support of the endomorphism family is asserted or assumed. Original Lean signature: theorem mode_support_finite (v : Fock) : (Function.support (fun k => U k v)).Finite"),
                Node("modeSum", "This is the locally finite finsum of the original paired modes evaluated on the input. Its finiteness is proved before linearity. Original Lean signature: def modeSum (v : Fock) : Fock", DescribeRole.Definition),
                Node("modeSum_eq_sum", "modeSum_add, modeSum_smul and M_eq_sum use finite captures to handle the original finsum. Original Lean signature: theorem modeSum_eq_sum (v : Fock) (N : \u2115) (hN : capture v \u2264 N) : modeSum v = \u2211 k \u2208 Finset.range N, U k v"),
                Node("modeSum_add", "The map_add field of the actual operator M uses this common-capture argument. One finite range contains the captures of v, w and v+w. Linearity of each original summand proves additivity on that common range. Original Lean signature: theorem modeSum_add (v w : Fock) : modeSum (v + w) = modeSum v + modeSum w"),
                Node("modeSum_smul", "The map_smul field of the actual operator M uses this common-capture argument. One finite range contains the captures of v and its scalar multiple. Scalar compatibility follows on this common range. Original Lean signature: theorem modeSum_smul (a : \u2102) (v : Fock) : modeSum (a \u2022 v) = a \u2022 modeSum v"),
                Node("M", "The actual mode sum is packaged as a complex linear endomorphism only after its linearity has been proved. Original Lean signature: def M : Module.End \u2102 Fock", DescribeRole.Definition),
                Node("M_eq_sum", "M_ket uses this statewise finite sum of the original operators to derive its count eigenvalue. Original Lean signature: theorem M_eq_sum (v : Fock) (N : \u2115) (hN : capture v \u2264 N) : M v = \u2211 k \u2208 Finset.range N, U k v"),
                Node("M_ket", "The coefficient formula, inverse identities, kernel reconstruction, eigenvalue witnesses and signed commutators use the actual-mode count action. The spectrum on each original occupation ket is derived from the original b and c actions and finite enumeration, rather than supplied as a hypothesis. Original Lean signature: theorem M_ket (S : Finset \u2115) : M (ket S) = (count S : \u2102) \u2022 ket S"),
                Node("diagonal", "A coefficient multiplier on the same original Finsupp carrier is used after deriving the actual mode count. It is not a replacement Fock representation. Original Lean signature: def diagonal (f : Finset \u2115 \u2192 \u2102) : Module.End \u2102 Fock", DescribeRole.Definition),
                Node("diagonal_ket", "M_eq_diagonal, the projection and inverse ket actions, and the coefficient proof use this generic multiplier action. Original Lean signature: @[simp] theorem diagonal_ket (f : Finset \u2115 \u2192 \u2102) (S : Finset \u2115) : diagonal f (ket S) = f S \u2022 ket S"),
                Node("diagonal_coefficient", "M_coefficient, P_coefficient and the site-3 coefficient test use this generic coefficient calculation. Original Lean signature: theorem diagonal_coefficient (f : Finset \u2115 \u2192 \u2102) (v : Fock) (S : Finset \u2115) : diagonal f v S = f S * v S"),
                Node("M_eq_diagonal", "M_coefficient uses this equality, proved from the actual-mode M_ket rather than assumed as a spectrum. Original Lean signature: theorem M_eq_diagonal : M = diagonal (fun S => (count S : \u2102))"),
                Node("M_coefficient", "M_support_subset and eigenvector_iff use this all-state formula; the retained Reg attempt also refers to its exact original telescope. For every original state and every finite occupation, the output coefficient is its input coefficient multiplied by the natural occupation count cast to Complex. Original Lean signature: theorem M_coefficient (v : Fock) (S : Finset \u2115) : M v S = (count S : \u2102) * v S"),
                Node("M_support_subset", "This is the support-preservation consequence of the actual M coefficient formula. Original Lean signature: theorem M_support_subset (v : Fock) : (M v).support \u2286 v.support"),
                Node("eigenvector_iff", "nonzero_eigenvalue_is_natural uses a nonzero supported coefficient to identify its count. An eigenvector may have several nonzero coefficients; every occupation in its support must carry exactly the displayed eigenvalue. Original Lean signature: theorem eigenvector_iff (v : Fock) (z : \u2102) : M v = z \u2022 v \u2194 \u2200 S \u2208 v.support, (count S : \u2102) = z"),
                Node("nonzero_eigenvalue_is_natural", "The forward directions of the full and literal-relative eigenvalue characterizations use this conclusion. A nonzero coefficient witnesses that the eigenvalue is a natural count. Nonnegativity is algebraic here; no positive ghost inner product is claimed. Original Lean signature: theorem nonzero_eigenvalue_is_natural (v : Fock) (z : \u2102) (hv : v \u2260 0) (he : M v = z \u2022 v) : \u2203 q : \u2115, z = (q : \u2102)"),
                Node("count_surjective_relative", "relative_eigenvalue_iff uses the constructed site-3-free finite set to witness every natural eigenvalue. Every natural number is attained by an occupation omitting site 3. The construction starts at the occupied site-1 ground and inserts a fresh regular site at each successor. Original Lean signature: theorem count_surjective_relative (q : \u2115) : \u2203 S : Finset \u2115, 3 \u2209 S \u2227 count S = q"),
                Node("P", "Projection onto all zero-count states of the full original carrier, including the site-3 partner. Original Lean signature: def P : Module.End \u2102 Fock", DescribeRole.Definition),
                Node("invM", "On a nonzero natural count use its complex reciprocal, and set the zero-count coefficient to zero. Original Lean signature: def invM : Module.End \u2102 Fock", DescribeRole.Definition),
                Node("P_ket", "Both actual inverse identities and the M-projection annihilation proofs use this zero-count indicator action. Original Lean signature: @[simp] theorem P_ket (S : Finset \u2115) : P (ket S) = (if count S = 0 then (1 : \u2102) else 0) \u2022 ket S"),
                Node("invM_ket", "Both actual inverse identities use this reciprocal action away from zero and its zero action at the ground. Original Lean signature: @[simp] theorem invM_ket (S : Finset \u2115) : invM (ket S) = (if count S = 0 then (0 : \u2102) else (count S : \u2102)\u207b\u00b9) \u2022 ket S"),
                Node("P_coefficient", "P_apply uses this indicator coefficient formula to recover exactly the two full-ground coefficients. Original Lean signature: theorem P_coefficient (v : Fock) (S : Finset \u2115) : P v S = if count S = 0 then v S else 0"),
                Node("M_mul_invM", "This is the right inverse identity for the original-mode M after subtracting its full zero-count projection. The original count followed by its spectral inverse is identity minus the full zero-count projection. Original Lean signature: theorem M_mul_invM : M * invM = 1 - P"),
                Node("invM_mul_M", "M_eq_zero_iff_P_eq_self uses this left inverse identity to reconstruct every vector killed by the original-mode M. The reverse product gives the same identity minus the full zero-count projection. Original Lean signature: theorem invM_mul_M : invM * M = 1 - P"),
                Node("M_mul_P", "The reverse direction of M_eq_zero_iff_P_eq_self uses this original-mode annihilation of the projected ground. Original Lean signature: theorem M_mul_P : M * P = 0"),
                Node("P_mul_M", "This is the reverse-order annihilation consequence for the actual-mode M and its full ground projection. Original Lean signature: theorem P_mul_M : P * M = 0"),
                Node("count_zero_iff", "P_apply uses the exhaustive original-site zero-count classification to eliminate all other coefficients. The complete zero-count occupation sets are precisely {1} and {1,3}. In particular the full kernel is not a single vacuum line. Original Lean signature: theorem count_zero_iff (S : Finset \u2115) : count S = 0 \u2194 S = {1} \u2228 S = {1, 3}"),
                Node("P_apply", "full_kernel_iff uses this two-coefficient ground reconstruction after the inverse argument. The full projection retains exactly the two original coefficients at {1} and {1,3}. Original Lean signature: theorem P_apply (v : Fock) : P v = v {1} \u2022 ket {1} + v {1, 3} \u2022 ket {1, 3}"),
                Node("M_eq_zero_iff_P_eq_self", "full_kernel_iff uses the inverse and M_mul_P to characterize precisely the fixed vectors of P. Original Lean signature: theorem M_eq_zero_iff_P_eq_self (v : Fock) : M v = 0 \u2194 P v = v"),
                Node("full_kernel_iff", "full_kernel and relative_kernel_iff use this exact reconstruction by the two original ground kets. Original Lean signature: theorem full_kernel_iff (v : Fock) : M v = 0 \u2194 \u2203 a d : \u2102, v = a \u2022 ket {1} + d \u2022 ket {1, 3}"),
                Node("full_kernel", "This is the full-Fock kernel endpoint, retaining both the site-3-free and site-3-occupied ground. The full zero eigenspace is exactly the complex span of the two displayed original kets. Original Lean signature: theorem full_kernel : LinearMap.ker M = Submodule.span \u2102 ({ket {1}, ket {1, 3}} : Set Fock)"),
                Node("b0_down", "relative_kernel_iff uses this simp calculation for the reverse implication on the site-3-free ground. Original Lean signature: @[simp] theorem b0_down : b 0 (ket {1}) = 0"),
                Node("b0_eq_zero_iff_coefficients", "relative_kernel_iff uses its coefficient test at {1,3} to eliminate the second ground coefficient. The literal original zero mode b at zero is annihilation at site 3. Its kernel is characterized by vanishing of every coefficient whose occupation contains site 3. Original Lean signature: theorem b0_eq_zero_iff_coefficients (v : Fock) : b 0 v = 0 \u2194 \u2200 S : Finset \u2115, 3 \u2208 S \u2192 v S = 0"),
                Node("relative_kernel_iff", "relative_kernel and relative_kernel_c1vac use this exact conjunction of the M and b-zero equations. Original Lean signature: theorem relative_kernel_iff (v : Fock) : (M v = 0 \u2227 b 0 v = 0) \u2194 \u2203 a : \u2102, v = a \u2022 ket {1}"),
                Node("relative_kernel", "This is the literal relative submodule endpoint: the intersection of the two actual operator kernels. Intersect the full count kernel with the literal original b-zero kernel. The result is exactly the line of ket {1}. Original Lean signature: theorem relative_kernel : LinearMap.ker M \u2293 LinearMap.ker (b 0) = Submodule.span \u2102 ({ket {1}} : Set Fock)"),
                Node("c1vac", "The named relative ground is the original c at one applied to the original empty vacuum. Original Lean signature: def c1vac : Fock", DescribeRole.Definition),
                Node("c1vac_eq", "relative_kernel_c1vac uses this identification with the original c at one acting on the empty vacuum. The original mode-vacuum formula identifies this state with ket {1}; it is not the empty occupation vacuum. Original Lean signature: theorem c1vac_eq : c1vac = ket {1}"),
                Node("relative_kernel_c1vac", "This is the named original-ground endpoint for the literal relative kernel. The literal joint kernel is exactly the complex multiples of the named original c-one vacuum. Original Lean signature: theorem relative_kernel_c1vac (v : Fock) : (M v = 0 \u2227 b 0 v = 0) \u2194 \u2203 a : \u2102, v = a \u2022 c1vac"),
                Node("relative_eigenvalue_iff", "eigenvalue_iff uses its site-3-free witnesses; it also gives the exact natural eigenvalue set under the literal relative condition. The algebraic point spectrum is exactly the natural numbers, even when the nonzero witnessing state must satisfy the literal relative b-zero condition. Original Lean signature: theorem relative_eigenvalue_iff (z : \u2102) : (\u2203 v : Fock, v \u2260 0 \u2227 b 0 v = 0 \u2227 M v = z \u2022 v) \u2194 \u2203 q : \u2115, z = (q : \u2102)"),
                Node("eigenvalue_iff", "This is the exact full algebraic eigenvalue-set endpoint; it concerns nonzero eigenvectors on the original finite-excitation carrier. The full algebraic point spectrum is exactly the natural numbers. This is not a topological spectral theorem for a Hilbert completion. Original Lean signature: theorem eigenvalue_iff (z : \u2102) : (\u2203 v : Fock, v \u2260 0 \u2227 M v = z \u2022 v) \u2194 \u2203 q : \u2115, z = (q : \u2102)"),
                Node("M_create_regular", "M_b_negative and M_c_negative use this regular-site count increase. Original Lean signature: theorem M_create_regular (j : \u2115) (hj1 : j \u2260 1) (hj3 : j \u2260 3) : M * create j - create j * M = create j"),
                Node("M_annihilate_regular", "M_b_positive and M_c_positive use this regular-site count decrease. Original Lean signature: theorem M_annihilate_regular (j : \u2115) (hj1 : j \u2260 1) (hj3 : j \u2260 3) : M * annihilate j - annihilate j * M = -annihilate j"),
                Node("M_annihilate_one", "The exceptional k=1 branch of M_b_negative uses the hole-creation sign at site 1. Original Lean signature: theorem M_annihilate_one : M * annihilate 1 - annihilate 1 * M = annihilate 1"),
                Node("M_create_one", "The exceptional k=1 branch of M_c_positive uses the hole-filling sign at site 1. Original Lean signature: theorem M_create_one : M * create 1 - create 1 * M = -create 1"),
                Node("M_b_negative", "This is the original negative-b commutator endpoint for every strictly positive natural index, including k=1. Every strictly negative original b mode raises the count by one, including the exceptional site-1 annihilation mode. Original Lean signature: theorem M_b_negative (k : \u2115) (hk : 0 < k) : M * b (-(k : \u2124)) - b (-(k : \u2124)) * M = b (-(k : \u2124))"),
                Node("M_c_negative", "This is the original negative-c commutator endpoint for every strictly positive natural index. Every strictly negative original c mode raises the count by one. Original Lean signature: theorem M_c_negative (k : \u2115) (hk : 0 < k) : M * c (-(k : \u2124)) - c (-(k : \u2124)) * M = c (-(k : \u2124))"),
                Node("M_b_positive", "This is the original positive-b commutator endpoint, with the negative sign, for every strictly positive natural index. Every strictly positive original b mode lowers the count by one. Original Lean signature: theorem M_b_positive (k : \u2115) (hk : 0 < k) : M * b (k : \u2124) - b (k : \u2124) * M = -b (k : \u2124)"),
                Node("M_c_positive", "This is the original positive-c commutator endpoint, with the negative sign and a separate k=1 proof. Every strictly positive original c mode lowers the count by one, including filling the exceptional site-1 hole. Original Lean signature: theorem M_c_positive (k : \u2115) (hk : 0 < k) : M * c (k : \u2124) - c (k : \u2124) * M = -c (k : \u2124)"),
                Paragraph(Text("The projection consequences follow directly from its zero-count indicator on each original ket. If count S is zero, P fixes ket S and invM kills it; otherwise P kills ket S and invM multiplies it by the reciprocal of count S. Thus P composed with itself equals P, equivalently P squared equals P, and both invM composed with P and P composed with invM vanish. The proved M ket action additionally gives M composed with P and P composed with M equal to zero. These exact consequences are checked by anonymous applications during verification; the generic projection-only identities have no retained named declarations. Likewise the inverse coefficient action is zero at count zero and otherwise the reciprocal count times the original coefficient. For the second full ground, b at zero acts on ket {1,3} as minus ket {1}: exactly one occupied site lies below 3 and erasing 3 leaves {1}. The relative-kernel proof instead uses b0_eq_zero_iff_coefficients at {1,3}; it does not consume a named special-ground sign lemma. Natural nonnegativity is inherent in count, and M is defined by modeSum; neither fact requires a separate theorem alias.")),
                Paragraph(Text("These are algebraic finite-excitation statements on the original carrier. The full zero-count kernel keeps the uncounted site 3; only intersection with the actual kernel of b at zero removes its partner. The positive and negative commutators require a strictly positive natural mode index. The inverse is zero on the full ground and inverts M only after subtracting that full projection. This supplier does not construct a quartet contraction, the matter tensor, the BRST charge or its nilpotence, homological perturbation, a no-ghost theorem, a Hilbert-space positivity theorem, Monster moonshine, a complete VOA/CFT, string theory or AdS/CFT. Those goals require their own constructions and proofs. No literature novelty is asserted.")))));
}
